// Clean the AI output into a flat, spreadsheet-safe row and flag anything a human should look at.
const src = $('Split PDF Attachments').item.json;
const o = $json.output || {};
const num = (v) => {
  if (typeof v === 'number') return Math.round(v * 100) / 100;
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : 0;
};
const isoDate = (v) => {
  if (!v) return '';
  const d = new Date(v);
  return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
};
const clean = (s) => String(s ?? '').trim();

let minConfidence = 0.85, pro = false;
try { minConfidence = Number($('Config').first().json.minConfidence ?? 0.85); pro = true; } catch (e) { /* free version has no Config node */ }
// Payment / tax IDs: keep letters and digits only, upper case ("DE89 3704..." -> "DE893704..."). Empty when absent.
const idClean = (s) => String(s ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const ein = String(o.vendor_ein ?? '').replace(/[^0-9]/g, '');

const subtotal = num(o.subtotal), tax = num(o.tax), total = num(o.total);
const lineItems = Array.isArray(o.line_items) ? o.line_items : [];
const confidence = Math.max(0, Math.min(1, Number(o.confidence) || 0));

const notes = [];
if (!clean(o.invoice_number)) notes.push('Missing invoice number');
if (!total) notes.push('Missing total');
if (subtotal && Math.abs(subtotal + tax - total) > 0.02) notes.push(`Math mismatch: ${subtotal} + ${tax} != ${total}`);
if (confidence < minConfidence) notes.push(`Low AI confidence (${confidence})`);

return {
  json: {
    processed_at: new Date().toISOString(),
    email_id: src.email_id,
    email_from: src.email_from,
    email_subject: src.email_subject,
    file_name: src.file_name,
    vendor_name: clean(o.vendor_name),
    vendor_email: clean(o.vendor_email),
    vendor_iban: idClean(o.vendor_iban),
    ...(pro ? { vendor_bic: idClean(o.vendor_bic) } : {}),
    vendor_vat_id: idClean(o.vendor_vat_id),
    ...(pro ? { vendor_ein: ein.length === 9 ? `${ein.slice(0, 2)}-${ein.slice(2)}` : ein } : {}),
    invoice_number: clean(o.invoice_number),
    po_number: clean(o.po_number),
    invoice_date: isoDate(o.invoice_date),
    due_date: isoDate(o.due_date),
    currency: (clean(o.currency) || 'USD').toUpperCase().slice(0, 3),
    subtotal,
    tax,
    total,
    line_count: lineItems.length,
    line_items_json: JSON.stringify(lineItems),
    confidence,
    status: notes.length ? 'needs_review' : 'extracted',
    review_notes: notes.join('; '),
  },
};

// Free: add the Invoice & Payment ID Validator demo result (IBAN, else EU VAT) to the invoice row.
// The demo endpoint needs no key but allows 10 calls per day per IP: a 429, an outage or an odd answer is
// recorded as "skipped" and never stops the run.
const inv = $('Normalize Invoice').item.json;
const r = $json;
const checked = inv.vendor_iban ? `IBAN ${inv.vendor_iban}` : inv.vendor_vat_id ? `VAT ${inv.vendor_vat_id}` : '';
let id_check = 'no_id', id_check_details = '';
if (!checked) {
  id_check = 'no_id';
} else if (r.invoice_number !== undefined) {
  id_check = 'skipped'; id_check_details = 'not checked';
} else if (r.error) {
  const msg = typeof r.error === 'string' ? r.error : (r.error.message || r.error.description || JSON.stringify(r.error));
  const capped = /429|demo_daily_limit|too many/i.test(`${msg} ${JSON.stringify(r.error).slice(0, 400)}`);
  id_check = 'skipped';
  id_check_details = capped ? 'demo limit reached (10 calls/day); a free RapidAPI key removes it' : `validator unavailable: ${String(msg).slice(0, 200)}`;
} else if (typeof r.valid === 'boolean') {
  id_check = r.valid ? 'valid' : 'invalid';
  id_check_details = r.valid
    ? `${checked}: valid${r.country ? ` (${r.country})` : ''}`
    : `${checked}: INVALID (${(r.errors || []).join(', ') || 'failed check'})`;
} else {
  id_check = 'skipped'; id_check_details = 'no result from validator';
}
const notes = [inv.review_notes, id_check === 'invalid' ? `Invalid vendor ${checked.split(' ')[0]}` : ''].filter(Boolean).join('; ');
return { json: { ...inv, id_check, id_check_details,
  status: id_check === 'invalid' ? 'needs_review' : inv.status, review_notes: notes } };
